defmodule Astraea.External.TffPrinter do
  @moduledoc """
  Prints `Astraea.Arena` clause sets as first-order TPTP TFF0 problems for
  first-order provers, via `Astraea.External.FolEncoding` (Leo-III's
  `leo.modules.output.ToTFF` for `MonoNative` encodings).

  The default encoding is applicative with lambda lifting:
    * every HOL type becomes a TFF sort (`$i`, user base types, `astraea_bool` for
      `$o` in term position, `astraea_fun_<type_id>` for function types)
    * every constant, Skolem symbol, and variable is nullary; application at function
      type `t` is the binary function `astraea_app_<t>`
    * Boolean terms are turned into formulas with `astraea_holds/1`
    * lambda abstractions and formulas in term position are lifted into fresh
      symbols over their free variables, defined by axioms `d<k>`

  Other encodings (SKI combinators, minimal-arity symbols, Boolean proxies) are
  selected with the `:encoding` option; see `Astraea.External.FolEncoding` for
  the variants and their soundness and completeness. The encoding is sound for
  refutations, so an unsatisfiable encoding implies an unsatisfiable clause set,
  but incomplete for higher-order clause sets, so `Satisfiable` answers carry no
  meaning there. Clause `i` is named `c<i>`, as in `Astraea.External.ThfPrinter`.
  """

  alias Astraea.{Arena, ProofChecker}
  alias Astraea.External.FolEncoding

  @doc """
  Renders `clauses` as a TFF0 problem. Options:
    * `:encoding` - first-order encoding (default `Astraea.External.FolEncoding.default/0`);
      its `:types` must be `:mono_native` (use `Astraea.External.FofPrinter` for guards)
    * `:role` - formula role for every clause (default `"axiom"`)
    * `:name_prefix` - prefix for clause formula names (default `"c"`)

  Raises `ArgumentError` on invalid encodings.
  """
  @spec problem(Arena.t(), [ProofChecker.clause()], keyword()) :: String.t()
  def problem(%Arena{} = arena, clauses, opts \\ []) do
    enc = FolEncoding.normalize!(Keyword.get(opts, :encoding))

    if enc[:types] != :mono_native do
      raise ArgumentError,
            "TFF output needs types: :mono_native, got #{inspect(enc[:types])} (use FofPrinter)"
    end

    problem = FolEncoding.encode(arena, clauses, Keyword.put(opts, :encoding, enc))
    render(problem)
  end

  @doc """
  Renders an encoded `Astraea.External.FolEncoding.Problem` as TFF0.
  """
  @spec render(FolEncoding.Problem.t()) :: String.t()
  def render(%FolEncoding.Problem{arena: arena} = problem) do
    binder = fn q, vars, body ->
      binders =
        Enum.map_intersperse(vars, ", ", fn {name, ty} ->
          [name, ": ", FolEncoding.sort(arena, ty)]
        end)

      ["(", if(q == :all, do: "! [", else: "? ["), binders, "]: ", body, ")"]
    end

    IO.iodata_to_binary([
      "% Generated by Astraea.External.TffPrinter (",
      describe(problem.encoding),
      ")\n",
      sort_decls(arena),
      symbol_decls(arena, problem.signature),
      Enum.map(problem.formulas, fn %{name: name, role: role, formula: f} ->
        ["tff(", name, ", ", role, ", ", FolEncoding.render_formula(f, binder), ").\n"]
      end)
    ])
  end

  @doc false
  def describe(enc), do: Enum.map_intersperse(enc, ", ", fn {k, v} -> "#{k}: #{v}" end)

  defp sort_decls(arena) do
    arena.type_table
    |> Enum.sort()
    |> Enum.flat_map(fn
      {_id, :i} ->
        []

      {id, _ty} ->
        [
          "tff(sort_",
          Integer.to_string(id),
          ", type, ",
          FolEncoding.sort(arena, id),
          ": $tType).\n"
        ]
    end)
  end

  defp symbol_decls(arena, signature) do
    signature
    |> Enum.sort()
    |> Enum.with_index()
    |> Enum.map(fn {{name, decl}, idx} ->
      ty =
        case decl do
          {:fun, args, res} -> signature(arena, args, FolEncoding.sort(arena, res))
          {:pred, args} -> signature(arena, args, "$o")
        end

      ["tff(sym_", Integer.to_string(idx), ", type, ", name, ": ", ty, ").\n"]
    end)
  end

  defp signature(_arena, [], res), do: res
  defp signature(arena, [arg], res), do: [FolEncoding.sort(arena, arg), " > ", res]

  defp signature(arena, args, res) do
    ["(", Enum.map_intersperse(args, " * ", &FolEncoding.sort(arena, &1)), ") > ", res]
  end
end
